1	package log
2	
3	import (
4		"bytes"
5		"encoding/binary"
6		"hash/crc32"
7	)
8	
9	// On-disk entry layouts, all integers little-endian. A segment file is a
10	// sequence of entries of three kinds:
11	//
12	// Single batch, written by Commit ("BCL1"):
13	//
14	//	magic   4 bytes  "BCL1"
15	//	seq     8 bytes  batch sequence number
16	//	count   4 bytes  number of records
17	//	records count × (4-byte length + opaque bytes)
18	//	crc32   4 bytes  IEEE checksum of everything before it
19	//
20	// Batch group, written by CommitGroup as one atomic unit ("BCLG"):
21	//
22	//	magic   4 bytes  "BCLG"
23	//	count   4 bytes  number of batches in the group
24	//	batches count × (8-byte seq + 4-byte record count + records)
25	//	crc32   4 bytes  IEEE checksum of everything before it
26	//
27	// Hole marker, written by crash recovery to make the sequences reserved
28	// by a torn tail permanent ("BCLH"):
29	//
30	//	magic   4 bytes  "BCLH"
31	//	count   4 bytes  number of reserved sequences
32	//	seqs    count × 8 bytes
33	//	crc32   4 bytes  IEEE checksum of everything before it
34	//
35	// The trailing checksum makes tampering detectable as ErrCorruptSegment
36	// when the segment is parsed. A torn write left by a crash is instead
37	// reported as a tail: a strict prefix of a valid entry, never a full
38	// entry with a bad checksum. A group entry is durable only as a whole —
39	// a truncated group is a tail and none of its batches become visible.
40	var (
41		segmentMagic = []byte{'B', 'C', 'L', '1'}
42		groupMagic   = []byte{'B', 'C', 'L', 'G'}
43		holeMagic    = []byte{'B', 'C', 'L', 'H'}
44	)
45	
46	const entryHeaderLen = 4 + 8 + 4
47	
48	// groupMember is one staged batch inside a group commit.
49	type groupMember struct {
50		seq     uint64
51		records [][]byte
52	}
53	
54	func encodeBatch(seq uint64, records [][]byte) []byte {
55		size := entryHeaderLen + 4
56		for _, r := range records {
57			size += 4 + len(r)
58		}
59		buf := make([]byte, 0, size)
60		buf = append(buf, segmentMagic...)
61		var tmp [8]byte
62		binary.LittleEndian.PutUint64(tmp[:], seq)
63		buf = append(buf, tmp[:]...)
64		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(records)))
65		buf = append(buf, tmp[:4]...)
66		for _, r := range records {
67			binary.LittleEndian.PutUint32(tmp[:4], uint32(len(r)))
68			buf = append(buf, tmp[:4]...)
69			buf = append(buf, r...)
70		}
71		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
72		return append(buf, tmp[:4]...)
73	}
74	
75	// encodeGroup encodes a batch group as a single entry. It also returns,
76	// for each member, the offset and length of its decodable body (seq +
77	// record count + records) relative to the start of the entry, so the
78	// index can point straight at one member of the group.
79	func encodeGroup(members []groupMember) (entry []byte, offs []int, lens []int) {
80		size := 4 + 4 + 4
81		for _, m := range members {
82			size += 8 + 4
83			for _, r := range m.records {
84				size += 4 + len(r)
85			}
86		}
87		buf := make([]byte, 0, size)
88		buf = append(buf, groupMagic...)
89		var tmp [8]byte
90		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(members)))
91		buf = append(buf, tmp[:4]...)
92		offs = make([]int, len(members))
93		lens = make([]int, len(members))
94		for i, m := range members {
95			offs[i] = len(buf)
96			binary.LittleEndian.PutUint64(tmp[:], m.seq)
97			buf = append(buf, tmp[:]...)
98			binary.LittleEndian.PutUint32(tmp[:4], uint32(len(m.records)))
99			buf = append(buf, tmp[:4]...)
100			for _, r := range m.records {
101				binary.LittleEndian.PutUint32(tmp[:4], uint32(len(r)))
102				buf = append(buf, tmp[:4]...)
103				buf = append(buf, r...)
104			}
105			lens[i] = len(buf) - offs[i]
106		}
107		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
108		return append(buf, tmp[:4]...), offs, lens
109	}
110	
111	// encodeHoles encodes a hole marker reserving the given sequences
112	// forever. Recovery writes it in place of a torn tail so the reserved
113	// sequences survive as permanent holes across reopens.
114	func encodeHoles(seqs []uint64) []byte {
115		buf := make([]byte, 0, 4+4+8*len(seqs)+4)
116		buf = append(buf, holeMagic...)
117		var tmp [8]byte
118		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(seqs)))
119		buf = append(buf, tmp[:4]...)
120		for _, seq := range seqs {
121			binary.LittleEndian.PutUint64(tmp[:], seq)
122			buf = append(buf, tmp[:]...)
123		}
124		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
125		return append(buf, tmp[:4]...)
126	}
127	
128	// decodeBody decodes one batch body (seq + record count + records) as
129	// located by the index. Unlike segment parsing, any inconsistency here
130	// is corruption: an indexed body was validated when the segment was
131	// parsed, so a mismatch means the file changed underneath the log.
132	func decodeBody(body []byte) (uint64, [][]byte, error) {
133		if len(body) < 12 {
134			return 0, nil, ErrCorruptSegment
135		}
136		seq := binary.LittleEndian.Uint64(body[:8])
137		count := binary.LittleEndian.Uint32(body[8:12])
138		records, pos, ok := parseRecords(body, 12, count)
139		if !ok || pos != len(body) {
140			return 0, nil, ErrCorruptSegment
141		}
142		return seq, records, nil
143	}
144	
145	type parsedBatch struct {
146		seq     uint64
147		records [][]byte
148		off     int // offset of the batch body within the segment
149		length  int // length of the batch body
150		// diskOff/diskLen/diskCRC describe the whole entry on disk (magic
151		// through trailing checksum) and the checksum it stores. The index
152		// sidecar records them so adoption can re-verify an entry against
153		// the segment without decoding any of its records.
154		diskOff int
155		diskLen int
156		diskCRC uint32
157	}
158	
159	type parsedHole struct {
160		off    int // offset of the marker's magic within the segment
161		length int // total length of the marker on disk, including its CRC
162		crc    uint32
163		seqs   []uint64
164	}
165	
166	// segmentTail describes an incomplete entry at the end of a segment: the
167	// remnant of a crash in the middle of a write.
168	type segmentTail struct {
169		off  int      // offset where the incomplete entry starts
170		seqs []uint64 // sequences the torn entry had already reserved
171	}
172	
173	// parseSegment decodes every complete entry in data, returning the
174	// committed batches (with the offsets of their bodies, for the index)
175	// and the durable hole markers. A truncated tail — trailing bytes that
176	// are only a prefix of an entry — is reported separately as the
177	// signature of a crash mid-write, along with every sequence the torn
178	// entry had already reserved. Any other inconsistency (unknown magic,
179	// bad checksum) yields ErrCorruptSegment.
180	func parseSegment(data []byte) ([]parsedBatch, []parsedHole, *segmentTail, error) {
181		var batches []parsedBatch
182		var holes []parsedHole
183		var off int
184		for off < len(data) {
185			rest := data[off:]
186			if len(rest) < len(segmentMagic) {
187				// A partial magic is a torn write only if it is a
188				// prefix of a valid magic; all magics share "BCL".
189				if !bytes.Equal(rest, segmentMagic[:len(rest)]) {
190					return nil, nil, nil, ErrCorruptSegment
191				}
192				return batches, holes, &segmentTail{off: off}, nil
193			}
194			switch {
195			case bytes.Equal(rest[:4], segmentMagic):
196				if len(rest) < entryHeaderLen {
197					tail := &segmentTail{off: off}
198					if len(rest) >= 12 {
199						tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(rest[4:12]))
200					}
201					return batches, holes, tail, nil
202				}
203				seq := binary.LittleEndian.Uint64(rest[4:12])
204				count := binary.LittleEndian.Uint32(rest[12:16])
205				pos := off + entryHeaderLen
206				records, npos, ok := parseRecords(data, pos, count)
207				if !ok {
208					return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
209				}
210				pos = npos
211				if len(data)-pos < 4 {
212					return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
213				}
214				crc := binary.LittleEndian.Uint32(data[pos : pos+4])
215				if crc32.ChecksumIEEE(data[off:pos]) != crc {
216					return nil, nil, nil, ErrCorruptSegment
217				}
218				batches = append(batches, parsedBatch{
219					seq: seq, records: records,
220					off: off + 4, length: pos - off - 4,
221					diskOff: off, diskLen: pos + 4 - off, diskCRC: crc,
222				})
223				off = pos + 4
224			case bytes.Equal(rest[:4], groupMagic):
225				tail := &segmentTail{off: off}
226				if len(rest) < 8 {
227					return batches, holes, tail, nil
228				}
229				count := binary.LittleEndian.Uint32(rest[4:8])
230				pos := off + 8
231				var members []parsedBatch
232				for i := uint32(0); i < count; i++ {
233					if len(data)-pos < 12 {
234						// Torn between or inside member headers;
235						// recover the member's sequence if whole.
236						if len(data)-pos >= 8 {
237							tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
238						}
239						return batches, holes, tail, nil
240					}
241					mOff := pos
242					seq := binary.LittleEndian.Uint64(data[pos : pos+8])
243					nrec := binary.LittleEndian.Uint32(data[pos+8 : pos+12])
244					tail.seqs = append(tail.seqs, seq)
245					records, npos, ok := parseRecords(data, pos+12, nrec)
246					if !ok {
247						return batches, holes, tail, nil
248					}
249					pos = npos
250					members = append(members, parsedBatch{seq: seq, records: records, off: mOff, length: pos - mOff})
251				}
252				if len(data)-pos < 4 {
253					return batches, holes, tail, nil
254				}
255				crc := binary.LittleEndian.Uint32(data[pos : pos+4])
256				if crc32.ChecksumIEEE(data[off:pos]) != crc {
257					return nil, nil, nil, ErrCorruptSegment
258				}
259				// Only a complete, checksummed group publishes its
260				// members; a torn group above publishes none.
261				for _, mb := range members {
262					mb.diskOff, mb.diskLen, mb.diskCRC = off, pos+4-off, crc
263					batches = append(batches, mb)
264				}
265				off = pos + 4
266			case bytes.Equal(rest[:4], holeMagic):
267				tail := &segmentTail{off: off}
268				if len(rest) < 8 {
269					return batches, holes, tail, nil
270				}
271				count := binary.LittleEndian.Uint32(rest[4:8])
272				pos := off + 8
273				var seqs []uint64
274				for i := uint32(0); i < count; i++ {
275					if len(data)-pos < 8 {
276						tail.seqs = append(tail.seqs, seqs...)
277						return batches, holes, tail, nil
278					}
279					seqs = append(seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
280					pos += 8
281				}
282				if len(data)-pos < 4 {
283					tail.seqs = append(tail.seqs, seqs...)
284					return batches, holes, tail, nil
285				}
286				crc := binary.LittleEndian.Uint32(data[pos : pos+4])
287				if crc32.ChecksumIEEE(data[off:pos]) != crc {
288					return nil, nil, nil, ErrCorruptSegment
289				}
290				holes = append(holes, parsedHole{
291					off: off, length: pos + 4 - off, crc: crc,
292					seqs: append(make([]uint64, 0, len(seqs)), seqs...),
293				})
294				off = pos + 4
295			default:
296				return nil, nil, nil, ErrCorruptSegment
297			}
298		}
299		return batches, holes, nil, nil
300	}
301	
302	// parseRecords decodes count records starting at pos. ok is false when
303	// the data runs out first, which callers read as a torn write.
304	func parseRecords(data []byte, pos int, count uint32) (records [][]byte, npos int, ok bool) {
305		records = make([][]byte, 0, min(int(count), 1<<20))
306		for i := uint32(0); i < count; i++ {
307			if len(data)-pos < 4 {
308				return nil, 0, false
309			}
310			n := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
311			pos += 4
312			if n < 0 || len(data)-pos < n {
313				return nil, 0, false
314			}
315			rec := make([]byte, n)
316			copy(rec, data[pos:pos+n])
317			pos += n
318			records = append(records, rec)
319		}
320		return records, pos, true
321	}
