1	// Package log implements an append-only, batch-commit segmented log.
2	//
3	// A writer stages a batch of opaque records with Append and publishes it
4	// atomically with Commit, or publishes several staged batches atomically
5	// with CommitGroup. Readers only ever see committed batches, in strictly
6	// increasing sequence order starting at 1. Reads locate each batch
7	// through a persistent segment-level index in a sidecar file
8	// ("index.idx"): Open adopts it incrementally, and when it is missing,
9	// truncated, version-mismatched, checksum-bad or contradictory to the
10	// segments, Open rebuilds it from the segment files, so losing the
11	// index never loses data.
12	package log
13	
14	import (
15		"bytes"
16		"encoding/binary"
17		"errors"
18		"fmt"
19		"hash/crc32"
20		"os"
21		"path/filepath"
22		"sort"
23		"strconv"
24		"strings"
25		"sync"
26	)
27	
28	var (
29		// ErrNotCommitted is returned when reading a sequence that has been
30		// staged with Append but not yet committed.
31		ErrNotCommitted = errors.New("log: batch not committed")
32		// ErrUnknownBatch is returned for sequence 0, sequences that were
33		// never reserved, sequences beyond the reserved range, and batches
34		// that have already been committed.
35		ErrUnknownBatch = errors.New("log: unknown batch")
36		// ErrCorruptSegment is returned when a segment file fails validation
37		// while opening or scanning the log.
38		ErrCorruptSegment = errors.New("log: corrupt segment")
39		// ErrInvalidOptions is returned by Open when the options are not
40		// usable, e.g. a non-positive segment capacity.
41		ErrInvalidOptions = errors.New("log: invalid options")
42		// ErrSyncFailed is returned by Commit and CommitGroup when
43		// Options.Sync is set and fsyncing the segment file fails. The
44		// batches stay staged and keep their reserved sequences; committing
45		// them again retries.
46		ErrSyncFailed = errors.New("log: sync failed")
47	)
48	
49	var errClosed = errors.New("log: closed")
50	
51	// syncFile fsyncs a segment file. It is a variable so tests can
52	// simulate sync failures.
53	var syncFile = func(f *os.File) error { return f.Sync() }
54	
55	// Options configures a Log opened with Open.
56	type Options struct {
57		// SegmentBytes is the capacity of one segment file in bytes. Once a
58		// non-empty segment would exceed it, the log rolls to a new segment.
59		// A single batch or group larger than the capacity occupies its own
60		// segment. Must be positive.
61		SegmentBytes int
62		// Sync makes Commit and CommitGroup fsync the segment file before
63		// returning, so a returned commit is durable.
64		Sync bool
65	}
66	
67	// Batch is a group of records identified by a single sequence number.
68	// A Batch returned by Append is staged; after Commit or CommitGroup it
69	// is readable.
70	type Batch struct {
71		seq     uint64
72		records [][]byte
73		owner   *Log
74	}
75	
76	// Seq returns the sequence number reserved for the batch.
77	func (b Batch) Seq() uint64 { return b.seq }
78	
79	// Records returns a copy of the batch's records.
80	func (b Batch) Records() [][]byte { return copyRecords(b.records) }
81	
82	// Segment describes one segment file by the committed sequences it holds.
83	type Segment struct {
84		FirstSeq uint64
85		LastSeq  uint64
86	}
87	
88	// entryRef locates one committed batch body inside a segment file. The
89	// persistent index sidecar stores the same locations; its loss or
90	// invalidation is always safe because Open rebuilds it from the
91	// segments. gen is the publication generation of the commit that
92	// published the batch; every member of a group commit shares one gen,
93	// which lets a streaming replay snapshot see the whole group or none of
94	// it.
95	type entryRef struct {
96		seg    int // segment file number
97		off    int // offset of the batch body within the segment
98		length int // length of the batch body
99		gen    uint64
100	}
101	
102	// Log is an append-only batch-commit log stored in a directory of
103	// segment files. It is safe for concurrent use, but the writer side is
104	// expected to be a single goroutine (see README Limits).
105	//
106	// The read and write paths are decoupled: writers take mu exclusively,
107	// while readers hold it only for the brief index and staged-state
108	// lookups. Segment file reads, decoding and user callbacks happen
109	// outside the lock, so a slow reader or a long replay never blocks a
110	// committing writer.
111	type Log struct {
112		dir  string
113		opts Options
114	
115		// mu guards the mutable index and write state below. Readers never
116		// hold it across file I/O, decoding or callbacks.
117		mu         sync.RWMutex
118		file       *os.File // current segment, nil until first write
119		fileSize   int
120		idxFile    *os.File // index sidecar, opened for append
121		idxSize    int
122		segIndex   int // index of the current segment file, 0 = none yet
123		curBatches int // committed batches in the current segment
124		nextSeq    uint64
125		staged     map[uint64][][]byte
126		index      map[uint64]entryRef
127		segs       []Segment // segments holding at least one committed batch
128		gen        uint64    // publication generation of the last commit
129		closed     bool
130	}
131	
132	// Open opens the log in dir, creating the directory if needed. The
133	// committed set is taken from the persistent index sidecar when it can
134	// be adopted incrementally; if the sidecar is missing, truncated, from
135	// another version, checksum-bad or contradictory to the segment files,
136	// Open transparently rebuilds it by scanning the segments once. Either
137	// path yields identical reads, replays, segment listings and errors.
138	//
139	// A half-written tail of the last segment — the remnant of a crash
140	// mid-write — is replaced by a durable hole marker without error and
141	// its reserved sequences stay permanent holes across reopens; any other
142	// inconsistency is ErrCorruptSegment.
143	func Open(dir string, opts Options) (*Log, error) {
144		if opts.SegmentBytes <= 0 {
145			return nil, ErrInvalidOptions
146		}
147		if err := os.MkdirAll(dir, 0o755); err != nil {
148			return nil, err
149		}
150		entries, err := os.ReadDir(dir)
151		if err != nil {
152			return nil, err
153		}
154		var indices []int
155		for _, e := range entries {
156			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
157				continue
158			}
159			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
160			if err != nil {
161				continue
162			}
163			indices = append(indices, n)
164		}
165		sort.Ints(indices)
166	
167		l := &Log{
168			dir:     dir,
169			opts:    opts,
170			nextSeq: 1,
171			staged:  make(map[uint64][][]byte),
172			index:   make(map[uint64]entryRef),
173		}
174	
175		// Segment sizes are all the segment metadata adoption needs; the
176		// contents are touched only by the cheap CRC pass, never decoded
177		// entry by entry.
178		sizes := make(map[int]int, len(indices))
179		for _, n := range indices {
180			st, err := os.Stat(l.segmentPath(n))
181			if err != nil {
182				return nil, err
183			}
184			sizes[n] = int(st.Size())
185		}
186	
187		snapshot, ok := l.adoptIndex(indices, sizes)
188		if !ok {
189			snapshot, err = l.rebuildFromSegments(indices)
190			if err != nil {
191				return nil, err
192			}
193		}
194		sortIndexSnapshot(&snapshot)
195		l.installSnapshot(snapshot, indices)
196	
197		if len(indices) > 0 {
198			l.segIndex = indices[len(indices)-1]
199			if err := l.openCurrent(); err != nil {
200				return nil, err
201			}
202		}
203		if err := l.openIndex(); err != nil {
204			return nil, err
205		}
206		return l, nil
207	}
208	
209	// installSnapshot populates the in-memory index, segment listing, staged
210	// holes and next-sequence counter from an adopted or rebuilt snapshot.
211	// Both open paths funnel through here so their observable state is
212	// identical. Entries must be ordered by (segment, disk offset); each
213	// entry (a single commit or one group) gets one publication generation.
214	func (l *Log) installSnapshot(p parsedIndex, indices []int) {
215		for i := range p.entries {
216			e := &p.entries[i]
217			l.gen++
218			for _, m := range e.members {
219				l.index[m.seq] = entryRef{seg: e.seg, off: m.off, length: m.length, gen: l.gen}
220				if m.seq >= l.nextSeq {
221					l.nextSeq = m.seq + 1
222				}
223			}
224		}
225		// Segment listing: one entry per physical segment that holds at
226		// least one committed batch.
227		segSeen := make(map[int]int)
228		for i := range p.entries {
229			e := &p.entries[i]
230			var first, last uint64
231			for j, m := range e.members {
232				if j == 0 {
233					first, last = m.seq, m.seq
234				}
235				if m.seq < first {
236					first = m.seq
237				}
238				if m.seq > last {
239					last = m.seq
240				}
241			}
242			if idx, known := segSeen[e.seg]; known {
243				if first < l.segs[idx].FirstSeq {
244					l.segs[idx].FirstSeq = first
245				}
246				if last > l.segs[idx].LastSeq {
247					l.segs[idx].LastSeq = last
248				}
249			} else {
250				segSeen[e.seg] = len(l.segs)
251				l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
252			}
253		}
254		// Holes reserve sequences permanently: they read as staged (never
255		// committed) and are never reused, across any number of reopens.
256		for i := range p.holes {
257			for _, seq := range p.holes[i].seqs {
258				if seq == 0 {
259					continue
260				}
261				if _, committed := l.index[seq]; !committed {
262					l.staged[seq] = nil
263				}
264				if seq >= l.nextSeq {
265					l.nextSeq = seq + 1
266				}
267			}
268		}
269		if len(indices) > 0 {
270			last := indices[len(indices)-1]
271			l.curBatches = 0
272			for i := range p.entries {
273				if p.entries[i].seg == last {
274					l.curBatches += len(p.entries[i].members)
275				}
276			}
277		}
278	}
279	
280	// sortIndexSnapshot orders a snapshot's records by (segment, offset),
281	// the canonical on-disk and publication order.
282	func sortIndexSnapshot(p *parsedIndex) {
283		sort.SliceStable(p.entries, func(i, j int) bool {
284			if p.entries[i].seg != p.entries[j].seg {
285				return p.entries[i].seg < p.entries[j].seg
286			}
287			return p.entries[i].off < p.entries[j].off
288		})
289		sort.SliceStable(p.holes, func(i, j int) bool {
290			if p.holes[i].seg != p.holes[j].seg {
291				return p.holes[i].seg < p.holes[j].seg
292			}
293			return p.holes[i].off < p.holes[j].off
294		})
295	}
296	
297	// adoptIndex is the incremental open path. It verifies the sidecar
298	// against the segment files without decoding record bodies: its records
299	// must tile a prefix of the segment files from offset zero, every
300	// on-disk CRC must match, and member locations must agree with the entry
301	// headers. Any framing defect, a truncated final record, a version
302	// mismatch or a contradiction makes it return ok=false and Open rebuilds
303	// from the segments instead.
304	//
305	// The segments may legitimately extend past a verified index — the
306	// crash window between the segment sync and the index record sync. That
307	// suffix (extra bytes of the last covered segment, plus any whole later
308	// segment) is parsed incrementally: complete entries get indexed, a
309	// torn tail of the last segment becomes a hole marker, so adoption
310	// still costs one small decode rather than a full scan.
311	func (l *Log) adoptIndex(indices []int, sizes map[int]int) (parsedIndex, bool) {
312		if len(indices) == 0 {
313			// No segments: nothing to index; openIndex creates the sidecar
314			// lazily with its header when the first commit lands.
315			return parsedIndex{}, true
316		}
317		data, err := l.readIndexBytes()
318		if err != nil {
319			return parsedIndex{}, false
320		}
321		p, tailLen, err := readIndexFile(data)
322		if err != nil || tailLen > 0 {
323			// Missing/truncated/foreign sidecar: the rebuild path owns
324			// these cases.
325			return parsedIndex{}, false
326		}
327		if len(p.entries) == 0 && len(p.holes) == 0 {
328			// A recordless sidecar is valid only when every segment is
329			// empty; otherwise the sidecar is simply behind and the
330			// rebuild path catches up.
331			for _, n := range indices {
332				if sizes[n] != 0 {
333					return parsedIndex{}, false
334				}
335			}
336			return p, true
337		}
338		covered, covEnd, ok := l.verifySidecar(p, indices, sizes)
339		if !ok {
340			return parsedIndex{}, false
341		}
342	
343		// Everything at or after covered is unverified suffix: the unindexed
344		// tail bytes of segment covered, then every whole later segment.
345		pos := 0
346		for pos < len(indices) && indices[pos] < covered {
347			pos++
348		}
349		var extra []diskRecord
350		for si := pos; si < len(indices); si++ {
351			n := indices[si]
352			raw, err := os.ReadFile(l.segmentPath(n))
353			if err != nil {
354				return parsedIndex{}, false
355			}
356			base := 0
357			if n == covered {
358				if covEnd > len(raw) {
359					return parsedIndex{}, false
360				}
361				base = covEnd
362			}
363			batches, markers, tail, perr := parseSegment(raw[base:])
364			if perr != nil {
365				// Tampering in the suffix surfaces through the rebuild path
366				// with the identical ErrCorruptSegment.
367				return parsedIndex{}, false
368			}
369			if tail != nil && si != len(indices)-1 {
370				return parsedIndex{}, false
371			}
372			for k := 0; k < len(batches); {
373				diskOff := batches[k].diskOff + base
374				j := k + 1
375				for j < len(batches) && batches[j].diskOff+base == diskOff {
376					j++
377				}
378				e := indexEntry{
379					seg:     n,
380					off:     diskOff,
381					length:  batches[k].diskLen,
382					diskCRC: batches[k].diskCRC,
383					members: make([]indexMember, 0, j-k),
384				}
385				for _, pb := range batches[k:j] {
386					e.members = append(e.members, indexMember{
387						seq: pb.seq, off: pb.off + base, length: pb.length,
388					})
389				}
390				p.entries = append(p.entries, e)
391				extra = append(extra, diskRecord{seg: n, off: diskOff, enc: encodeEntryRecord(e)})
392				k = j
393			}
394			for _, h := range markers {
395				ih := indexHole{
396					seg: n, off: h.off + base, length: h.length, diskCRC: h.crc,
397					seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
398				}
399				p.holes = append(p.holes, ih)
400				extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
401			}
402			if tail != nil {
403				keep := make([]uint64, 0, len(tail.seqs))
404				for _, seq := range tail.seqs {
405					if seq > 0 {
406						keep = append(keep, seq)
407					}
408				}
409				if err := l.rewriteTail(n, base+tail.off, keep); err != nil {
410					return parsedIndex{}, false
411				}
412				if len(keep) > 0 {
413					marker := encodeHoles(keep)
414					crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
415					ih := indexHole{
416						seg: n, off: base + tail.off, length: len(marker), diskCRC: crc,
417						seqs: append(make([]uint64, 0, len(keep)), keep...),
418					}
419					p.holes = append(p.holes, ih)
420					extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
421				}
422			}
423		}
424	
425		// Persist the incrementally recovered records so later opens adopt
426		// them too. A crash during this append leaves a torn final index
427		// record, and the next open simply rebuilds.
428		if len(extra) > 0 {
429			if err := l.appendAdoptedSuffix(extra); err != nil {
430				return parsedIndex{}, false
431			}
432		}
433		return p, true
434	}
435	
436	// appendAdoptedSuffix appends incrementally recovered records to the
437	// sidecar and fsyncs it. Failure means the caller rebuilds instead.
438	func (l *Log) appendAdoptedSuffix(recs []diskRecord) error {
439		sort.SliceStable(recs, func(i, j int) bool {
440			if recs[i].seg != recs[j].seg {
441				return recs[i].seg < recs[j].seg
442			}
443			return recs[i].off < recs[j].off
444		})
445		f, err := os.OpenFile(l.indexPath(), os.O_WRONLY|os.O_APPEND, 0o644)
446		if err != nil {
447			return err
448		}
449		defer f.Close()
450		for _, r := range recs {
451			if _, err := f.Write(r.enc); err != nil {
452				return err
453			}
454		}
455		return f.Sync()
456	}
457	
458	// sidecarRec is one physical record the index claims.
459	type sidecarRec struct {
460		seg    int
461		off    int
462		length int
463		crc    uint32
464		entry  *indexEntry
465		hole   *indexHole
466	}
467	
468	// verifySidecar checks an already-framed parse against the physical
469	// segments without decoding any record body. It returns the last segment
470	// the index covers and the offset immediately after its records there.
471	//
472	// The covered segments must be a prefix of the segment files in the
473	// directory; within each one records must be strictly ordered, start at
474	// offset zero and tile without gaps or overlap. Every covered segment
475	// except the last must end exactly at the file size (nothing
476	// unindexed); the last one may stop short, leaving a suffix for
477	// incremental parsing. Every stored disk CRC is recomputed, and entry
478	// headers (magic and group membership layout) are checked.
479	func (l *Log) verifySidecar(p parsedIndex, indices []int, sizes map[int]int) (coveredSeg int, coveredEnd int, ok bool) {
480		if len(indices) == 0 {
481			return 0, 0, false
482		}
483		recs := make([]sidecarRec, 0, len(p.entries)+len(p.holes))
484		for i := range p.entries {
485			e := &p.entries[i]
486			recs = append(recs, sidecarRec{seg: e.seg, off: e.off, length: e.length, crc: e.diskCRC, entry: e})
487		}
488		for i := range p.holes {
489			h := &p.holes[i]
490			recs = append(recs, sidecarRec{seg: h.seg, off: h.off, length: h.length, crc: h.diskCRC, hole: h})
491		}
492		sort.SliceStable(recs, func(i, j int) bool {
493			if recs[i].seg != recs[j].seg {
494				return recs[i].seg < recs[j].seg
495			}
496			return recs[i].off < recs[j].off
497		})
498	
499		known := make(map[int]bool, len(indices))
500		for _, n := range indices {
501			known[n] = true
502		}
503		covered := false
504		seenSeq := make(map[uint64]bool)
505		var f *os.File
506		openSeg := -1
507		closeFile := func() {
508			if f != nil {
509				f.Close()
510				f = nil
511				openSeg = -1
512			}
513		}
514		defer closeFile()
515	
516		prevSeg, prevEnd := -1, 0
517		for i := range recs {
518			r := &recs[i]
519			if !known[r.seg] || r.off < 0 || r.length < 16 {
520				return 0, 0, false
521			}
522			if r.seg != prevSeg {
523				// A new covered segment: the previous one must be tiled to
524				// its EOF, and the covered segments must be a prefix with no
525				// unindexed segment file in between.
526				if prevSeg != -1 && prevEnd != sizes[prevSeg] {
527					return 0, 0, false
528				}
529				if covered {
530					next := 0
531					found := false
532					for _, n := range indices {
533						if n > prevSeg {
534							next, found = n, true
535							break
536						}
537					}
538					if !found || r.seg != next || r.off != 0 {
539						return 0, 0, false
540					}
541				} else {
542					if r.seg != indices[0] || r.off != 0 {
543						return 0, 0, false
544					}
545				}
546				covered = true
547				prevSeg = r.seg
548				prevEnd = 0
549				closeFile()
550				var err error
551				f, err = os.Open(l.segmentPath(r.seg))
552				if err != nil {
553					return 0, 0, false
554				}
555				openSeg = r.seg
556			}
557			if openSeg != r.seg || r.off != prevEnd || r.off+r.length > sizes[r.seg] {
558				return 0, 0, false
559			}
560			if !l.verifyDiskRecord(f, r, seenSeq) {
561				return 0, 0, false
562			}
563			prevEnd = r.off + r.length
564		}
565		lastSeg := recs[len(recs)-1].seg
566		lastEnd := prevEnd
567	
568		// Every segment file before the last covered one must carry at
569		// least one index record (no unindexed segment in the middle).
570		refSegs := map[int]bool{}
571		for i := range recs {
572			refSegs[recs[i].seg] = true
573		}
574		for _, n := range indices {
575			if n < lastSeg && !refSegs[n] {
576				return 0, 0, false
577			}
578		}
579		return lastSeg, lastEnd, true
580	}
581	
582	// verifyDiskRecord checks one index claim against the segment without
583	// holding the entry in memory: a small header read, a streaming CRC over
584	// a fixed-size scratch buffer, and 8-byte reads of group-member
585	// sequences. It never decodes record bodies.
586	func (l *Log) verifyDiskRecord(f *os.File, r *sidecarRec, seenSeq map[uint64]bool) bool {
587		var hdr [16]byte
588		if _, err := f.ReadAt(hdr[:12], int64(r.off)); err != nil {
589			return false
590		}
591		// Stream the entry's CRC-covered prefix through one reused buffer,
592		// then compare against the stored trailing checksum.
593		h := crc32.NewIEEE()
594		buf := make([]byte, 64*1024)
595		remaining := r.length - 4
596		at := int64(r.off)
597		for remaining > 0 {
598			n := len(buf)
599			if n > remaining {
600				n = remaining
601			}
602			if _, err := f.ReadAt(buf[:n], at); err != nil {
603				return false
604			}
605			h.Write(buf[:n])
606			remaining -= n
607			at += int64(n)
608		}
609		var crcBytes [4]byte
610		if _, err := f.ReadAt(crcBytes[:], at); err != nil {
611			return false
612		}
613		stored := binary.LittleEndian.Uint32(crcBytes[:])
614		if h.Sum32() != stored || stored != r.crc {
615			return false
616		}
617	
618		switch {
619		case r.entry != nil:
620			e := r.entry
621			switch {
622			case bytes.Equal(hdr[:4], segmentMagic):
623				return len(e.members) == 1 &&
624					e.members[0].seq == binary.LittleEndian.Uint64(hdr[4:12]) &&
625					e.members[0].off == r.off+4 &&
626					e.members[0].length == r.length-8 &&
627					markSeen(e.members, seenSeq)
628			case bytes.Equal(hdr[:4], groupMagic):
629				if uint32(len(e.members)) != binary.LittleEndian.Uint32(hdr[4:8]) {
630					return false
631				}
632				bodyStart := r.off + 8
633				for i, m := range e.members {
634					rel := m.off - r.off
635					if m.length <= 0 || rel < 8 || rel+m.length > r.length-4 {
636						return false
637					}
638					if i == 0 {
639						if m.off != bodyStart {
640							return false
641						}
642					} else {
643						prev := e.members[i-1]
644						if m.off != prev.off+prev.length {
645							return false
646						}
647					}
648					if i == len(e.members)-1 && m.off+m.length != r.off+r.length-4 {
649						return false
650					}
651					var seqBytes [8]byte
652					if _, err := f.ReadAt(seqBytes[:], int64(m.off)); err != nil {
653						return false
654					}
655					if m.seq != binary.LittleEndian.Uint64(seqBytes[:]) {
656						return false
657					}
658				}
659				return markSeen(e.members, seenSeq)
660			default:
661				return false
662			}
663		case r.hole != nil:
664			h2 := r.hole
665			if !bytes.Equal(hdr[:4], holeMagic) ||
666				uint32(len(h2.seqs)) != binary.LittleEndian.Uint32(hdr[4:8]) ||
667				r.length != 4+4+8*len(h2.seqs)+4 {
668				return false
669			}
670			// The reserved sequences themselves must agree with the marker,
671			// not just their count.
672			seqBytes := make([]byte, 8*len(h2.seqs))
673			if len(seqBytes) > 0 {
674				if _, err := f.ReadAt(seqBytes, int64(r.off+8)); err != nil {
675					return false
676				}
677				for i, seq := range h2.seqs {
678					if seq == 0 || seenSeq[seq] ||
679						seq != binary.LittleEndian.Uint64(seqBytes[8*i:8*i+8]) {
680						return false
681					}
682				}
683			}
684			return true
685		default:
686			return false
687		}
688	}
