701	// rebuildFromSegments is the fallback open path: it decodes every
702	// segment exactly as a historical open did, recovers a torn tail of the
703	// last segment into a durable hole marker, and finally persists a fresh
704	// index snapshot. Tampering anywhere but the last segment's tail stays
705	// ErrCorruptSegment.
706	func (l *Log) rebuildFromSegments(indices []int) (parsedIndex, error) {
707		var p parsedIndex
708		for i, n := range indices {
709			data, err := os.ReadFile(l.segmentPath(n))
710			if err != nil {
711				return parsedIndex{}, err
712			}
713			batches, markers, tail, err := parseSegment(data)
714			if err != nil {
715				return parsedIndex{}, err
716			}
717			if tail != nil && i != len(indices)-1 {
718				// A half-written tail is a crash remnant only in the last
719				// segment; anywhere else it is tampering.
720				return parsedIndex{}, ErrCorruptSegment
721			}
722			for k := 0; k < len(batches); {
723				// Members of one group entry share diskOff; a single commit
724				// is an entry with one member.
725				diskOff := batches[k].diskOff
726				j := k + 1
727				for j < len(batches) && batches[j].diskOff == diskOff {
728					j++
729				}
730				e := indexEntry{
731					seg:     n,
732					off:     batches[k].diskOff,
733					length:  batches[k].diskLen,
734					diskCRC: batches[k].diskCRC,
735					members: make([]indexMember, 0, j-k),
736				}
737				for _, pb := range batches[k:j] {
738					e.members = append(e.members, indexMember{seq: pb.seq, off: pb.off, length: pb.length})
739				}
740				p.entries = append(p.entries, e)
741				k = j
742			}
743			for _, h := range markers {
744				p.holes = append(p.holes, indexHole{
745					seg: n, off: h.off, length: h.length, diskCRC: h.crc,
746					seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
747				})
748			}
749			if tail != nil {
750				// Replace the torn entry with a durable hole marker so its
751				// reserved sequences stay permanent holes, then index the
752				// replacement marker as part of the fresh snapshot.
753				keep := make([]uint64, 0, len(tail.seqs))
754				for _, seq := range tail.seqs {
755					if seq > 0 {
756						keep = append(keep, seq)
757					}
758				}
759				if err := l.rewriteTail(n, tail.off, keep); err != nil {
760					return parsedIndex{}, err
761				}
762				if len(keep) > 0 {
763					marker := encodeHoles(keep)
764					crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
765					p.holes = append(p.holes, indexHole{
766						seg: n, off: tail.off, length: len(marker), diskCRC: crc,
767						seqs: append(make([]uint64, 0, len(keep)), keep...),
768					})
769				}
770			}
771		}
772		sortIndexSnapshot(&p)
773		if err := l.writeIndexSnapshot(p); err != nil {
774			return parsedIndex{}, err
775		}
776		return p, nil
777	}
