851	// CommitGroup makes several staged batches durable and readable as one
852	// atomic unit: a single segment write and, with Options.Sync, a single
853	// segment fsync covering the whole group, followed by one index record
854	// synced once. Each batch keeps the sequence it reserved at Append, and
855	// the batches become visible in that reserved order — the merge never
856	// reorders them. If any batch is not staged — including one already
857	// committed — nothing is written and the error is ErrUnknownBatch. If
858	// either fsync fails, the segment entry and the index record are rolled
859	// back and every batch stays staged with its reserved sequence; the
860	// error is ErrSyncFailed and retrying the group commits it without
861	// duplicating entries. A crash can never leave half of the group
862	// visible: the group is either wholly durable or wholly staged, and
863	// sequences reserved by a torn group stay permanent holes.
864	func (l *Log) CommitGroup(batches []Batch) ([]uint64, error) {
865		l.mu.Lock()
866		defer l.mu.Unlock()
867		if l.closed {
868			return nil, errClosed
869		}
870		if len(batches) == 0 {
871			return nil, nil
872		}
873		members := make([]groupMember, len(batches))
874		seqs := make([]uint64, len(batches))
875		seen := make(map[uint64]struct{}, len(batches))
876		for i, b := range batches {
877			recs, ok := l.staged[b.seq]
878			if !ok || b.owner != l {
879				return nil, ErrUnknownBatch
880			}
881			if _, dup := seen[b.seq]; dup {
882				return nil, ErrUnknownBatch
883			}
884			seen[b.seq] = struct{}{}
885			members[i] = groupMember{seq: b.seq, records: recs}
886			seqs[i] = b.seq
887		}
888		entry, offs, lens := encodeGroup(members)
889		idxBefore := l.idxSize
890		base, err := l.writeEntry(entry)
891		if err != nil {
892			return nil, err
893		}
894		if l.opts.Sync {
895			if err := syncFile(l.file); err != nil {
896				// Every batch stays staged and keeps its reserved sequence;
897				// a later CommitGroup retries. Drop the un-synced group
898				// entry so the retry cannot duplicate it.
899				l.rollbackEntry(base, idxBefore)
900				return nil, fmt.Errorf("%w: %v", ErrSyncFailed, err)
901			}
902		}
903		imembers := make([]indexMember, len(members))
904		for i, m := range members {
905			imembers[i] = indexMember{seq: m.seq, off: base + offs[i], length: lens[i]}
906		}
907		rec := encodeEntryRecord(indexEntry{
908			seg:     l.segIndex,
909			off:     base,
910			length:  len(entry),
911			diskCRC: binary.LittleEndian.Uint32(entry[len(entry)-4:]),
912			members: imembers,
913		})
914		if err := l.appendIndexRecord(rec); err != nil {
915			// The index never advertises a batch whose commit failed: roll
916			// both files back and leave the whole group staged for retry.
917			l.rollbackEntry(base, idxBefore)
918			return nil, err
919		}
920		first, last := seqs[0], seqs[0]
921		l.gen++
922		for i, m := range members {
923			delete(l.staged, m.seq)
924			l.index[m.seq] = entryRef{seg: l.segIndex, off: base + offs[i], length: lens[i], gen: l.gen}
925			if m.seq < first {
926				first = m.seq
927			}
928			if m.seq > last {
929				last = m.seq
930			}
931		}
932		l.commitSpan(first, last, len(members))
933		return seqs, nil
934	}
