936	// Read returns the records of the committed batch with the given
937	// sequence, located directly through the segment-level index. A staged
938	// but uncommitted sequence yields ErrNotCommitted; sequence 0,
939	// never-reserved sequences, and sequences beyond the reserved range
940	// yield ErrUnknownBatch.
941	//
942	// The lock is held only for the index lookup; the segment file is read
943	// and the body decoded without it, so a slow read never blocks writers.
944	func (l *Log) Read(seq uint64) ([][]byte, error) {
945		l.mu.RLock()
946		if l.closed {
947			l.mu.RUnlock()
948			return nil, errClosed
949		}
950		ref, ok := l.index[seq]
951		if !ok {
952			_, staged := l.staged[seq]
953			l.mu.RUnlock()
954			if staged {
955				return nil, ErrNotCommitted
956			}
957			return nil, ErrUnknownBatch
958		}
959		l.mu.RUnlock()
960		return l.readRef(seq, ref)
961	}
