1022	// Segments lists the segments that hold committed batches, in file
1023	// order, each with its first and last committed sequence.
1024	func (l *Log) Segments() []Segment {
1025		l.mu.RLock()
1026		defer l.mu.RUnlock()
1027		out := make([]Segment, len(l.segs))
1028		copy(out, l.segs)
1029		return out
1030	}
