1032	// Close closes the current segment file and the index sidecar. The log
1033	// must not be used afterwards.
1034	func (l *Log) Close() error {
1035		l.mu.Lock()
1036		defer l.mu.Unlock()
1037		if l.closed {
1038			return nil
1039		}
1040		l.closed = true
1041		var err error
1042		if l.file != nil {
1043			err = l.file.Close()
1044		}
1045		if l.idxFile != nil {
1046			if ierr := l.idxFile.Close(); err == nil {
1047				err = ierr
1048			}
1049		}
1050		return err
1051	}
1052	
1053	// readRef loads the records of a committed batch straight from its
1054	// segment file. It performs no locking and must be called without l.mu
1055	// held: the segment read and body decode happen entirely on the read
1056	// path, outside the writer lock. The on-disk bytes are immutable once
1057	// committed (only the torn tail of the very last segment is ever
1058	// rewritten, and that tail never has an index entry), so a ref captured
1059	// under the read lock stays valid afterwards. The returned records are
1060	// freshly decoded, so callers can mutate them without affecting the
1061	// log or later reads.
1062	func (l *Log) readRef(seq uint64, ref entryRef) ([][]byte, error) {
1063		f, err := os.Open(l.segmentPath(ref.seg))
1064		if err != nil {
1065			return nil, err
1066		}
1067		defer f.Close()
1068		body := make([]byte, ref.length)
1069		if _, err := f.ReadAt(body, int64(ref.off)); err != nil {
1070			return nil, err
1071		}
1072		got, records, err := decodeBody(body)
1073		if err != nil {
1074			return nil, err
1075		}
1076		if got != seq {
1077			return nil, ErrCorruptSegment
1078		}
1079		return records, nil
1080	}
