1173	func (l *Log) openCurrent() error {
1174		f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
1175		if err != nil {
1176			return err
1177		}
1178		st, err := f.Stat()
1179		if err != nil {
1180			f.Close()
1181			return err
1182		}
1183		l.file = f
1184		l.fileSize = int(st.Size())
1185		return nil
1186	}
