340		rec[0] = 0xee // mutating the caller's slice must not affect the staged batch
341		if _, err := l.Commit(b); err != nil {
342			t.Fatalf("Commit: %v", err)
343		}
344		got, err := l.Read(b.Seq())
345		if err != nil {
346			t.Fatalf("Read: %v", err)
347		}
348		if !reflect.DeepEqual(got[0], []byte{0x00, 0xff, 0x0a, 0x00}) {
349			t.Fatalf("Read = %v, want original bytes", got[0])
350		}
351		got[0][1] = 0x11 // mutating the read result must not affect the log
352		again, _ := l.Read(b.Seq())
353		if again[0][1] != 0xff {
354			t.Fatalf("log content mutated through returned slice")
355		}
356	}
