19	// across multiple segments, and returns the directory + options.
20	func seedLog(t *testing.T, segBytes int) (string, log.Options) {
21		t.Helper()
22		dir := t.TempDir()
23		opts := log.Options{SegmentBytes: segBytes, Sync: true}
24		l := open(t, dir, opts)
25		commit(t, l, []byte("one"))
26		commit(t, l, []byte("two"), []byte("three"))
27		var gs []log.Batch
28		for _, s := range []string{"g1", "g2"} {
29			b, err := l.Append([][]byte{[]byte(s)})
