51		want := map[uint64][][]byte{
52			1: {[]byte("one")},
53			2: {[]byte("two"), []byte("three")},
54			3: {[]byte("g1")},
55			4: {[]byte("g2")},
56			5: {},
57		}
58		for seq, recs := range want {
59			got, err := l.Read(seq)
60			if err != nil || !reflect.DeepEqual(got, recs) {
61				t.Fatalf("Read(%d) = %q, %v; want %q", seq, got, err, recs)
62			}
63		}
64		var seqs []uint64
65		if err := l.Scan(1, func(b log.Batch) error {
66			seqs = append(seqs, b.Seq())
67			return nil
68		}); err != nil {
69			t.Fatalf("Scan: %v", err)
70		}
71		if !reflect.DeepEqual(seqs, []uint64{1, 2, 3, 4, 5}) {
72			t.Fatalf("scan seqs = %v, want [1 2 3 4 5]", seqs)
73		}
74		segs := l.Segments()
75		if len(segs) == 0 || segs[0].FirstSeq != 1 {
76			t.Fatalf("segments = %+v, want non-empty starting at 1", segs)
77		}
