236	// decodeBody decodes one batch body (seq + record count + records) as
237	// located by the index. Unlike segment parsing, any inconsistency here
238	// is corruption: an indexed body was validated when the segment was
239	// parsed, so a mismatch means the file changed underneath the log.
240	func decodeBody(body []byte) (uint64, [][]byte, error) {
241		if len(body) < 12 {
242			return 0, nil, ErrCorruptSegment
243		}
244		seq := binary.LittleEndian.Uint64(body[:8])
245		count := binary.LittleEndian.Uint32(body[8:12])
246		records, pos, ok := parseRecords(body, 12, count)
247		if !ok || pos != len(body) {
248			return 0, nil, ErrCorruptSegment
249		}
