253	type parsedBatch struct {
254		seq     uint64
255		records [][]byte
256		off     int // offset of the batch body within the segment
257		length  int // length of the batch body
258		// diskOff/diskLen/diskCRC describe the whole entry on disk (magic
259		// through trailing checksum) and the checksum it stores. The index
260		// sidecar records them so adoption can re-verify an entry against
261		// the segment without decoding any of its records.
262		diskOff int
263		diskLen int
264		diskCRC uint32
265	}
266	
267	type parsedHole struct {
268		off    int // offset of the marker's magic within the segment
269		length int // total length of the marker on disk, including its CRC
270		crc    uint32
271		seqs   []uint64
272	}
273	
274	// segmentTail describes an incomplete entry at the end of a segment: the
275	// remnant of a crash in the middle of a write.
276	type segmentTail struct {
277		off  int      // offset where the incomplete entry starts
278		seqs []uint64 // sequences the torn entry had already reserved
279	}
280	
281	// parseSegment decodes every complete entry in data, returning the
282	// committed batches (with the offsets of their bodies, for the index)
283	// and the durable hole markers. A truncated tail — trailing bytes that
284	// are only a prefix of an entry — is reported separately as the
285	// signature of a crash mid-write, along with every sequence the torn
286	// entry had already reserved. Any other inconsistency (unknown magic,
287	// bad checksum) yields ErrCorruptSegment.
288	func parseSegment(data []byte) ([]parsedBatch, []parsedHole, *segmentTail, error) {
289		var batches []parsedBatch
290		var holes []parsedHole
291		var off int
