			n = remaining
		}
		if _, err := f.ReadAt(buf[:n], at); err != nil {
			return false
		}
		h.Write(buf[:n])
		remaining -= n
		at += int64(n)
	}
	var crcBytes [4]byte
	if _, err := f.ReadAt(crcBytes[:], at); err != nil {
		return false
	}
	stored := binary.LittleEndian.Uint32(crcBytes[:])
	if h.Sum32() != stored || stored != r.crc {
		return false
