		case bytes.Equal(hdr[:4], segmentMagic):
			return len(e.members) == 1 &&
				e.members[0].seq == binary.LittleEndian.Uint64(hdr[4:12]) &&
				e.members[0].off == r.off+4 &&
				e.members[0].length == r.length-8 &&
