				rel := m.off - r.off
				if m.length <= 0 || rel < 8 || rel+m.length > r.length-4 {
					return false
				}
				if i == 0 {
					if m.off != bodyStart {
						return false
					}
				} else {
					prev := e.members[i-1]
					if m.off != prev.off+prev.length {
