// decodeKeyedBody decodes one keyed-framed body (2-byte key length +
// key + seq + record count + records) as located by the index. A zero
// key length is legal only for an anonymous member of a BCLK group and
// yields id == "". Any framing defect is corruption: the encoder only
// writes valid frames.
func decodeKeyedBody(body []byte) (uint64, string, [][]byte, error) {
	if len(body) < 2 {
		return 0, "", nil, ErrCorruptSegment
	}
	n := int(binary.LittleEndian.Uint16(body[:2]))
	pos := 2
	var id string
	if n > 0 {
		if n > maxKeyLen || len(body)-pos < n {
			return 0, "", nil, ErrCorruptSegment
		}
		raw := body[pos : pos+n]
		if bytes.IndexByte(raw, 0) >= 0 || !utf8.Valid(raw) {
			return 0, "", nil, ErrCorruptSegment
		}
		id = string(raw)
		pos += n
	}
	if len(body)-pos < 12 {
		return 0, "", nil, ErrCorruptSegment
	}
	seq := binary.LittleEndian.Uint64(body[pos : pos+8])
	count := binary.LittleEndian.Uint32(body[pos+8 : pos+12])
	records, epos, ok := parseRecords(body, pos+12, count)
	if !ok || epos != len(body) {
		return 0, "", nil, ErrCorruptSegment
	}
	return seq, id, records, nil
}

