// key + seq + record count + records) as located by the index. A zero
// key length yields id == "" and is legal only for an anonymous member
// of a BCLK group; readRef only reaches it for keyed refs. Any framing
// defect is corruption: the encoder only ever writes valid frames.
func decodeKeyedBody(body []byte) (uint64, string, [][]byte, error) {
	id, n, ok, bad := parseKey(body, 0)
	if bad || !ok || len(body)-n < 12 {
		return 0, "", nil, ErrCorruptSegment
	}
