	k1, _ := l.AppendIdempotent("key-a", [][]byte{[]byte("r1"), []byte("r2")})
	k2, _ := l.AppendIdempotent("key-b", nil) // empty record set, keyed
	if _, err := l.CommitGroup([]log.Batch{anon, k1, k2}); err != nil {
		t.Fatalf("CommitGroup: %v", err)
