	}
	for _, k := range bad {
		if _, err := l.AppendIdempotent(k, [][]byte{[]byte("r")}); !errors.Is(err, log.ErrInvalidBatchID) {
			t.Fatalf("key %q: err = %v, want ErrInvalidBatchID", k, err)
		}
